 text('span',String(a.apt),row).className='picker-apartment-number';text('span',owners.join(' / ')||'לא רשומים בעלי דירה',row).className='picker-owner-names';text('span',tenants.join(' / ')||'לא רשומים שוכרים',row).className=tenants.length?'picker-tenant-names':'picker-tenant-names picker-no-tenants';
