 const roles=apartment?.availableRoles||['committee','owner',...(apartment?.tenants?.some(name=>typeof name==='string'&&!['','-','אין'].includes(name.trim()))?['tenant']:[])];
 const select=$('viewer-role'),previous=select.value;
